273	void ProjectPersistence::adopt_current_project(bool in_place_reset)
274	{
275	    m_attached_aux_dir = m_workspace.auxiliary_data_dir();
276	    m_attached         = true;
277	    // A calibration generator's own new project: the same project goes on.
278	    // The generator can move the project folder more than once (JusPrin's
279	    // calibration project, then OrcaSlicer's own), so every boundary while
280	    // it runs continues the project; continuing_project() disarms it.
281	    if (m_continuing_project) {
282	        m_dirty = true;
283	        flush();
284	        return;
285	    }
286	    m_draft.clear();
287	
288	    if (in_place_reset) {
289	        // A full in-place reset is a new project boundary: earlier state does
290	        // not carry into it.
291	        if (m_config.managed_root.empty()) {
292	            std::error_code ec;
293	            fs::remove_all(jusprin_data_dir(), ec);
294	        }
295	        start_fresh_identity();
296	        return;
297	    }
298	
299	    // An external archive can carry the old auxiliary document. Read it once
300	    // for migration; managed snapshots never write authoritative state there.

300	    // for migration; managed snapshots never write authoritative state there.
301	    const fs::path legacy_state = fs::path(m_attached_aux_dir) / kJusPrinDirName / kStateFileName;
302	    const std::string state_text = read_file(m_config.managed_root.empty() ? fs::path(state_file_path()) : legacy_state);
303	    if (state_text.empty()) {
304	        start_fresh_identity();
305	        return;
306	    }
307	
308	    ProjectStateDocument loaded;
309	    const ProjectStateDocument::LoadResult result = loaded.load(state_text);
310	    if (result != ProjectStateDocument::LoadResult::Loaded) {
311	        // Keep the file it cannot read, broken or from a newer JusPrin, for
312	        // inspection, then start over: the model opens with a new chat history.
313	        std::error_code ec;
314	        fs::rename(legacy_state, legacy_state.string() + (result == ProjectStateDocument::LoadResult::Newer ? ".newer" : ".corrupt"), ec);
315	        start_fresh_identity();
316	        return;
317	    }
318	    m_document = std::move(loaded);
319	
320	    if (!m_config.managed_root.empty()) {
321	        // A copied or reopened external archive is an import, even when it
322	        // carries an identity that already has a managed head on this host.
323	        if (fs::exists(fs::path(m_config.managed_root) / m_document.project_id() / "HEAD"))
324	            m_document.fork_identity("p-" + m_config.uuid(), m_config.clock());
325	        // The attachments, and the pictures the chats' records sent.
326	        for (const char* folder : {"attachments", kChatRecordsDir}) {
327	            const fs::path old_folder = fs::path(m_attached_aux_dir) / kJusPrinDirName / folder;
328	            const fs::path local_folder = fs::path(jusprin_data_dir()) / folder;
329	            if (!fs::is_directory(old_folder))
330	                continue;
331	            for (const auto& entry : fs::recursive_directory_iterator(old_folder)) {
332	                const fs::path target = local_folder / fs::relative(entry.path(), old_folder);
333	                if (entry.is_directory())
334	                    fs::create_directories(target);
335	                else if (entry.is_regular_file()) {
336	                    fs::create_directories(target.parent_path());
337	                    fs::copy_file(entry.path(), target, fs::copy_options::overwrite_existing);
338	                }
339	            }
340	        }
341	    }
342	
343	    // A stream or run interrupted by the crash/restart cannot resume.
344	    m_document.normalize_interrupted_state();
345	    if (!m_config.managed_root.empty()) {
346	        m_draft = m_document.draft();
347	    }
348	
349	    m_dirty = true;
350	    flush();
351	    notify_document_replaced();
352	}
