434	        throw std::logic_error("model restore requires a managed project document");
435	    ProjectStateDocument current;
436	    if (current.load(current_state) != ProjectStateDocument::LoadResult::Loaded || !current.has_identity())
437	        throw std::runtime_error("current project document is invalid during model restore");
438	    current.normalize_interrupted_state();
