    12	std::string image_thumbnail_data_url(const std::string& bytes, int long_edge)
    13	{
    14	    wxMemoryInputStream input(bytes.data(), bytes.size());
    15	    wxImage             image;
    16	    if (!image.LoadFile(input, wxBITMAP_TYPE_ANY) || !image.IsOk())
    17	        return {};
    18	    const double scale = std::min(1.0, double(long_edge) / std::max(image.GetWidth(), image.GetHeight()));
    19	    if (scale < 1.0)
    20	        image.Rescale(std::max(1, int(image.GetWidth() * scale)), std::max(1, int(image.GetHeight() * scale)),
    21	                      wxIMAGE_QUALITY_HIGH);
    22	    image.SetOption(wxIMAGE_OPTION_QUALITY, 85);
    23	    wxMemoryOutputStream output;
    24	    if (!image.SaveFile(output, wxBITMAP_TYPE_JPEG))
    25	        return {};
    26	    std::string encoded(output.GetSize(), '\0');
    27	    output.CopyTo(encoded.data(), encoded.size());
    28	    return encoded.empty() ? std::string() : "data:image/jpeg;base64," + base64_encode(encoded);
    29	}
