    31	std::optional<EncodedImage> image_for_model(const std::string& bytes, int long_edge, std::size_t max_bytes)
    32	{
    33	    wxMemoryInputStream input(bytes.data(), bytes.size());
    34	    wxImage             image;
    35	    if (!image.LoadFile(input, wxBITMAP_TYPE_ANY) || !image.IsOk())
    36	        return std::nullopt;
    37	    const int longest = std::max(image.GetWidth(), image.GetHeight());
    38	    if (longest <= long_edge && bytes.size() <= max_bytes)
    39	        return std::nullopt;
    40	    if (longest > long_edge) {
    41	        const double scale = double(long_edge) / longest;
    42	        image.Rescale(std::max(1, int(image.GetWidth() * scale)), std::max(1, int(image.GetHeight() * scale)),
    43	                      wxIMAGE_QUALITY_HIGH);
    44	    }
    45	    const bool transparent = image.HasAlpha() || image.HasMask();
    46	    if (!transparent)
    47	        image.SetOption(wxIMAGE_OPTION_QUALITY, 85);
    48	    wxMemoryOutputStream output;
    49	    if (!image.SaveFile(output, transparent ? wxBITMAP_TYPE_PNG : wxBITMAP_TYPE_JPEG))
    50	        return std::nullopt;
    51	    EncodedImage encoded{transparent ? "image/png" : "image/jpeg", std::string(output.GetSize(), '\0')};
    52	    output.CopyTo(encoded.bytes.data(), encoded.bytes.size());
    53	    // A re-encoding that came out no smaller is no help.
    54	    if (encoded.bytes.empty() || encoded.bytes.size() >= bytes.size())
    55	        return std::nullopt;
    56	    return encoded;
    57	}
