    38	json anthropic_from_responses(const json& output)
    39	{
    40	    json blocks = json::array();
    41	    for (const json& item : output) {
    42	        const std::string type = item.at("type").get<std::string>();
    43	        if (type == "message") {
    44	            for (const json& part : item.at("content"))
    45	                if (part.at("type") == "output_text")
    46	                    blocks.push_back(json{{"type", "text"}, {"text", part.at("text")}});
