 19	std::string sha256_hex(const std::string& bytes)
 20	{
 21	    std::array<unsigned char, SHA256_DIGEST_LENGTH> digest{};
 22	    SHA256(reinterpret_cast<const unsigned char*>(bytes.data()), bytes.size(), digest.data());
 23	    std::ostringstream out;
 24	    out << std::hex << std::setfill('0');
 25	    for (unsigned char byte : digest)
 26	        out << std::setw(2) << static_cast<unsigned int>(byte);
 27	    return out.str();
 28	}
