 30	std::string sha256_file_hex(const std::string& path)
 31	{
 32	    std::ifstream in(std::filesystem::u8path(path), std::ios::binary);
 33	    if (!in)
 34	        throw std::runtime_error("cannot read " + path);
 35	    SHA256_CTX context;
 36	    SHA256_Init(&context);
 37	    std::array<char, 1 << 16> buffer{};
 38	    while (in.read(buffer.data(), buffer.size()) || in.gcount() > 0)
 39	        SHA256_Update(&context, buffer.data(), static_cast<std::size_t>(in.gcount()));
 40	    if (in.bad())
 41	        throw std::runtime_error("cannot read " + path);
 42	    std::array<unsigned char, SHA256_DIGEST_LENGTH> digest{};
 43	    SHA256_Final(digest.data(), &context);
 44	    std::ostringstream out;
 45	    out << std::hex << std::setfill('0');
 46	    for (unsigned char byte : digest)
 47	        out << std::setw(2) << static_cast<unsigned int>(byte);
 48	    return out.str();
 49	}
