124	{
125	    namespace fs = std::filesystem;
126	    const fs::path dir     = kept_gcode_dir(project_dir);
127	    const fs::path package = dir / (hash + ".gcode.3mf");
128	    if (kept_gcode_copy(project_dir, hash).empty() || !fs::exists(package))
129	        return std::nullopt;
130	    const fs::path config = dir / (hash + ".config.3mf");
131	    return KeptPackage{package.u8string(), fs::exists(config) ? config.u8string() : std::string()};
