134	std::string kept_package_hash(const GcodeRecord& record)
135	{
136	    for (auto destination = record.destinations.rbegin(); destination != record.destinations.rend(); ++destination)
137	        if (!destination->package_hash.empty())
138	            return destination->package_hash;
139	    return {};
140	}
