142	std::string gcode_display_name(const GcodeRecord& record)
143	{
144	    for (auto destination = record.destinations.rbegin(); destination != record.destinations.rend(); ++destination)
145	        if (destination->kind == GcodeDestination::Kind::Export && !destination->path.empty())
146	            return std::filesystem::u8path(destination->path).filename().u8string();
147	    return record.plate_name;
148	}
