150	std::optional<std::string> manufacturing_input_hash(const Workspace::WorkspaceSnapshot& snapshot,
151	                                                    std::size_t                         plate_index)
152	{
153	    if (plate_index >= snapshot.plates.size())
154	        return std::nullopt;
155	
156	    const Workspace::WorkspacePlate& plate = snapshot.plates[plate_index];
157	    json objects = json::array();
158	    for (const Workspace::WorkspaceObject& object : plate.objects) {
159	        json instances = json::array();
160	        for (const Workspace::ObjectTransform& transform : object.instances)
161	            instances.push_back(json{{"position", transform.position},
162	                                     {"rotation", transform.rotation},
163	                                     {"scale", transform.scale}});
164	        // Object display names and session-scoped IDs are intentionally not
165	        // manufacturing inputs. Geometry changes exposed by this workspace
166	        // surface appear as object/instance topology or transforms.
167	        objects.push_back(json{{"instances", std::move(instances)}});
168	    }
169	    const json canonical{{"format", "jusprin-manufacturing-input-v1"},
170	                         {"plateIndex", plate_index},
171	                         {"printerPreset", snapshot.setup.printer_preset},
172	                         {"materialPreset", snapshot.setup.filament_preset},
173	                         {"objects", std::move(objects)}};
174	    return sha256_hex(canonical.dump());
175	}
176	
177	std::optional<GcodeRecord> gcode_record(const Workspace::WorkspaceSnapshot& snapshot, std::size_t plate_index)
178	{
179	    const std::optional<std::string> hash = manufacturing_input_hash(snapshot, plate_index);
180	    if (!hash)
181	        return std::nullopt;
182	    const Workspace::WorkspacePlate& plate = snapshot.plates[plate_index];
183	    GcodeRecord record;
184	    record.plate_index              = plate_index;
185	    record.plate_name               = plate.name;
186	    record.printer                  = snapshot.setup.printer_preset;
187	    record.material                 = snapshot.setup.filament_preset;
188	    record.process                  = snapshot.setup.process_preset;
189	    record.manufacturing_input_hash = *hash;
190	    // An estimate OrcaSlicer did not give stays zero, which the record reads
191	    // as not recorded.
192	    if (plate.estimate) {
193	        if (plate.estimate->has_time)
194	            record.statistics.print_time_seconds = plate.estimate->print_time_seconds;
195	        if (plate.estimate->has_material)
196	            record.statistics.material_grams = plate.estimate->material_grams;
197	        if (plate.estimate->has_cost)
198	            record.statistics.material_cost = plate.estimate->material_cost;
199	    }
200	    return record;
201	}
