bool ProjectStateDocument::normalize_interrupted_state()
{
    bool changed = false;
    for (json& conversation : m_doc["conversations"])
        for (json& entry : conversation["messages"])
            if (entry.value("state", "") == "streaming") {
                entry["state"] = "stopped";
                changed        = true;
            }
    for (json& entry : m_doc["toolActivities"]) {
        // A state a newer build added is its to judge.
        const std::optional<ToolState> state = tool_state_from(entry.value("state", "running"));
        if (state && !tool_state_terminal(*state)) {
            entry["state"] = "cancelled";
            changed        = true;
        }
    }
    if (changed)
        touch();
    return changed;
}

