    } catch (const json::exception& error) {
        throw RuntimeError("jusprin-agent-bridge: " + (type.empty() ? std::string("envelope") : type) + " " +
                           (envelope_id.empty() ? std::string("(no id)") : envelope_id) + ": " + error.what());
